# test_summarize.py

import pytest
from summarize import summarize

@pytest.mark.parametrize('input,output', [
    (
        [
            {'region': 'North', 'revenue': '100'},
            {'region': 'North', 'revenue': '200'},
            {'region': 'South', 'revenue': '150'},
            {'region': 'South', 'revenue': 'abc'},  # invalid, should be ignored
            {'region': 'East', 'revenue': None},    # missing, should be ignored
        ],
        {'North': 300.0, 'South': 150.0}
    ),
    (
        [
            {'region': 'West', 'revenue': '0'},
            {'region': 'West', 'revenue': '0'},
        ],
        {'West': 0.0}
    ),
    (
        [
            {'region': 'Central', 'revenue': '250'},
            {'region': 'Central', 'revenue': '300'},
            {'region': 'Central', 'revenue': 'xyz'},  # invalid, should be ignored
        ],
        {'Central': 550.0}
    ),
])

def test_summarize(input, output):
    assert summarize(input) == output
